parameters.jsCode:
const body = $json.body || $json;

const studentName = body.studentName || 'Dave Lionel KAMENI';
const studentPhone = (body.studentPhone || '237672364124').replace(/[^0-9]/g, '');
const studentEmail = body.studentEmail || 'etudiant@campus360.app';
const jobTitle = body.jobTitle || 'Stagiaire Développeur';
const companyName = body.companyName || 'Entreprise Partenaire';
const recruiterPhone = (body.recruiterPhone || body.companyPhone || '237670009988').replace(/[^0-9]/g, '');
const recruiterEmail = body.recruiterEmail || 'rh@entreprise.com';
const matchScore = body.matchScore || 94;
const matchingSkills = Array.isArray(body.matchingSkills) ? body.matchingSkills.join(', ') : (body.matchingSkills || 'Compétences clés validées');
const refCode = body.applicationId ? `CAMPUS-${body.applicationId.slice(0, 6).toUpperCase()}` : `CAMPUS-${Date.now().toString().slice(-6)}`;

const recruiterPitch = `📢 *Nouvelle Candidature Reçue — Campus 360*

Bonjour *${companyName}*,

Un nouveau profil qualifié vient de postuler à votre offre de stage : *${jobTitle}*.

👤 *Candidat :* ${studentName}
🎯 *Score d'adéquation IA :* ${matchScore}%
💡 *Points forts :* ${matchingSkills}
🆔 *Référence dossier :* ${refCode}

📄 Le CV officiel 2 colonnes et la lettre de motivation personnalisée sont prêts pour examen.

Pour contacter directement le candidat :
📞 WhatsApp : https://wa.me/${studentPhone}
✉️ Email : ${studentEmail}`;

const studentReceipt = `✅ *Candidature Transmise avec Succès — Campus 360*

Bonjour *${studentName}*,

Votre dossier pour le stage de *${jobTitle}* chez *${companyName}* a été transmis directement au recruteur avec succès.

🆔 *Référence Dossier :* ${refCode}
📅 *Délai de réponse moyen :* 3 à 5 jours ouvrés.
💡 *Conseil :* Si vous n'avez pas de retour d'ici 7 jours, une relance polie automatique sera préparée dans votre espace Suivi.`;

return [{
  json: {
    refCode,
    studentName,
    studentPhone,
    studentEmail,
    jobTitle,
    companyName,
    recruiterPhone,
    recruiterEmail,
    recruiterPitch,
    studentReceipt,
    submittedAt: new Date().toISOString()
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  number: $('Formater Notifications RH & Candidat').item.json.studentPhone,
  text: $('Formater Notifications RH & Candidat').item.json.studentReceipt
}) }}

parameters.responseBody:
={{ JSON.stringify({
  success: true,
  message: 'Candidature routée avec succès vers le recruteur et le candidat',
  reference: $('Formater Notifications RH & Candidat').item.json.refCode,
  deliveredToRecruiter: true,
  deliveredToCandidate: true
}) }}
